<?php require 'config/database.php'; $id=(int)($_GET['id']??0); $pageTitle=$id?'Edit Student':'Add Student'; $s=['roll_no'=>'','name'=>'','email'=>'','phone'=>'','department'=>'','semester'=>1]; if($id){$q=$pdo->prepare('SELECT * FROM students WHERE id=?');$q->execute([$id]);$s=$q->fetch();if(!$s)die('Student not found');} if($_SERVER['REQUEST_METHOD']==='POST'){$data=[trim($_POST['roll_no']),trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['department']),(int)$_POST['semester']]; try{if($id){$q=$pdo->prepare('UPDATE students SET roll_no=?,name=?,email=?,phone=?,department=?,semester=? WHERE id=?');$q->execute(array_merge($data,[$id]));}else{$q=$pdo->prepare('INSERT INTO students(roll_no,name,email,phone,department,semester) VALUES(?,?,?,?,?,?)');$q->execute($data);}header('Location: students.php');exit;}catch(PDOException $e){$error='Roll number or email already exists.';}} require 'includes/header.php'; ?>
<h2 class="mb-3"><?=$id?'Edit':'Add'?> Student</h2><?php if(isset($error)):?><div class="alert alert-danger"><?=$error?></div><?php endif;?><div class="card shadow-sm"><div class="card-body"><form method="post"><div class="row g-3"><div class="col-md-6"><label class="form-label">Roll No</label><input required class="form-control" name="roll_no" value="<?=htmlspecialchars($s['roll_no'])?>"></div><div class="col-md-6"><label class="form-label">Name</label><input required class="form-control" name="name" value="<?=htmlspecialchars($s['name'])?>"></div><div class="col-md-6"><label class="form-label">Email</label><input required type="email" class="form-control" name="email" value="<?=htmlspecialchars($s['email'])?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?=htmlspecialchars($s['phone'])?>"></div><div class="col-md-8"><label class="form-label">Department</label><select required name="department" class="form-select"><option value="">Choose</option><?php foreach(['Computer Science','Software Engineering','Information Technology','Artificial Intelligence'] as $d):?><option <?=$s['department']===$d?'selected':''?>><?=$d?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Semester</label><select name="semester" class="form-select"><?php for($i=1;$i<=8;$i++):?><option <?=$s['semester']==$i?'selected':''?>><?=$i?></option><?php endfor;?></select></div></div><button class="btn btn-primary mt-4">Save Student</button> <a class="btn btn-secondary mt-4" href="students.php">Cancel</a></form></div></div><?php require 'includes/footer.php'; ?>
